Return ONLY JSON shaped like {"name":"short add-on title","updates":[{"path":"relative/path.json","content":"complete file text"}]}. Use exact existing paths when editing. New paths must be relative and safe. Return an empty updates array if no safe, relevant change can be made. Do not return markdown.`;const response=await fetch(state.url+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json',...(state.key?{Authorization:'Bearer '+state.key}:{})},body:JSON.stringify({model:state.model||'local-model',messages:[{role:'system',content:'You are Blocksmith, a careful Minecraft Bedrock add-on engineer. Return only the requested JSON patch data, and keep changes focused.'},{role:'user',content}],temperature:.2,max_tokens:12000}),signal:AbortSignal.timeout(180000)});if(!response.ok)throw Error(`Model server returned HTTP ${response.status}`);const data=await response.json();let text=data.choices?.[0]?.message?.content||'';if(Array.isArray(text))text=text.map(part=>typeof part==='string'?part:part.text||'').join('');text=text.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const result=JSON.parse(text);if(!Array.isArray(result.updates))throw Error('Model response did not contain an updates array.');if(result.updates.length>100)throw Error('Model returned too many file changes.');const seen=new Set();let total=0;const updates=[];for(const item of result.updates){const path=safeUpdatePath(item?.path);if(!path||typeof item.content!=='string')throw Error('Model returned an unsafe path or non-text update.');const key=path.toLowerCase();if(seen.has(key))throw Error(`Model returned duplicate file updates: ${path}`);seen.add(key);const bytes=new Blob([item.content]).size;if(bytes>MAX_ENTRY_BYTES)throw Error(`Model update exceeds the per-file safety limit: ${path}`);total+=bytes;if(total>MAX_EXTRACTED_BYTES)throw Error('Model updates exceed the expanded-size safety limit.');const existing=state.uploadedAddon.archive.file(path);if(existing?.dir)throw Error(`Cannot overwrite a directory: ${path}`);if(!existing&&Object.keys(state.uploadedAddon.archive.files).some(name=>name.toLowerCase()===key))throw Error(`Path conflicts with an existing file: ${path}`);if(/\.json$/i.test(path)){try{JSON.parse(item.content)}catch(error){throw Error(`Invalid JSON in ${path}: ${error.message}`)}}updates.push({path,content:item.content})}return{name:typeof result.name==='string'&&result.name.trim()?result.name.trim():state.uploadedAddon.file.name.replace(/\.mcaddon$/i,''),updates}}

