(async()=>{
 const source=new JSZip();
 const binary=Uint8Array.from([0,255,1,128,42,13,10,0]);
 source.file('behavior_pack/manifest.json','{"format_version":2,"header":{"name":"Before"}}');
 source.file('textures/opaque.bin',binary);
